import backtrader as bt


class VolatilityBreakoutStrategy(bt.Strategy):
    params = (
        ('N', 5),
        ('pct_up', 0.03),
        ('tp_pct', 0.06),
        ('sl_pct', 0.03),
        ('vol_thresh', 0.01),
        ('position_usdt', 100.0),
        ('use_atr_filter', True),
        ('mode', 'test'),
    )

    def __init__(self):
        self.pct_change = bt.indicators.PercentChange(self.data.close, period=self.p.N)
        self.atr = bt.indicators.ATR(self.data, period=14)
        self.order = None
        self.stop_order = None
        self.limit_order = None

    def notify_order(self, order):
        if order.status in (order.Completed, order.Canceled, order.Margin, order.Rejected):
            if order == self.order:
                self.order = None
            if order == self.stop_order:
                self.stop_order = None
            if order == self.limit_order:
                self.limit_order = None

    def next(self):
        if self.order or self.stop_order or self.limit_order:
            return
        if self.position:
            return

        if self.pct_change[0] >= self.p.pct_up:
            vol_ok = True
            if self.p.use_atr_filter:
                vol_ok = (self.atr[0] / self.data.close[0]) >= self.p.vol_thresh

            if vol_ok:
                price = self.data.close[0]
                size = self.p.position_usdt / price
                tp_price = price * (1.0 + self.p.tp_pct)
                sl_price = price * (1.0 - self.p.sl_pct)

                self.order, self.stop_order, self.limit_order = self.buy_bracket(
                    size=size,
                    exectype=bt.Order.Market,
                    stopprice=sl_price,
                    limitprice=tp_price,
                )
